CREATE TABLE payment_closure(execution_id UUID PRIMARY KEY REFERENCES payment_execution(execution_id),payment_id VARCHAR(50) NOT NULL UNIQUE REFERENCES payment(payment_id),
 phase VARCHAR(40) NOT NULL CHECK(phase IN ('SETTLEMENT_REQUESTED','SETTLED','PAYOUT_REQUESTED','PAYOUT_COMPLETION_REQUESTED','RECONCILIATION_REQUESTED','COMPLETED','REVIEW_REQUIRED')),
 failure_code VARCHAR(100),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
